export class AbortError extends Error { constructor(reason?: unknown){ super("The operation was aborted"); this.name="AbortError"; ... } }
```

Actually use DOMException when available. Simpler: create error with name "AbortError".

```ts
function createAbortError(reason?: unknown): Error {
  if (typeof DOMException !== "undefined") return new DOMException("The operation was aborted", "AbortError");
  const e = new Error("The operation was aborted") as Error & { cause?: unknown };
  e.name = "AbortError";
  e.cause = reason;
  return e;
}
```

Default sleep:

```ts
const defaultSleep: Sleeper = (ms, signal) => new Promise((resolve, reject) => {
  const t = setTimeout(() => { cleanup(); resolve(); }, ms);
  const onAbort = () => { cleanup(); clearTimeout(t); reject(createAbortError(signal?.reason)); };
  const cleanup = () => signal?.removeEventListener("abort", onAbort);
  if (signal?.aborted) { onAbort(); return; }
  signal?.addEventListener("abort", onAbort);
});
```

retry function:

```ts
export async function retry<T>(fn: () => Promise<T> | T, opts: RetryOptions = {}): Promise<T> {
  const attempts = opts.attempts ?? 3;
  const base = opts.baseDelayMs ?? 100;
  const max = opts.maxDelayMs ?? Infinity;
  const factor = opts.factor ?? 2;
  const jitter = opts.jitter ?? 0;
  const sleep = opts.sleep ?? defaultSleep;
  const random = opts.random ?? Math.random;
  const isRetryable = opts.isRetryable ?? (() => true);
  const signal = opts.signal;

  const throwIfAborted = () => { if (signal?.aborted) throw createAbortError(signal.reason); };

  throwIfAborted();
  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt === attempts) break;
      if (!isRetryable(error, attempt)) break;
      throwIfAborted();
      const exp = Math.min(max, base * Math.pow(factor, attempt - 1));
      const delay = exp * (1 - jitter + jitter * random());
      opts.onRetry?.({ error, attempt, delayMs: delay });
      await sleep(delay, signal);
      throwIfAborted();
    }
  }
  throw lastError;
}
```

